head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = 'ULDSTF30206.xml';
scwin.key_acpt_no;
scwin.key_reg_yn;
scwin.key_mkt_nm;
scwin.cmb_ColIndex;
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
};

//부모창에서 필요변수 저장
scwin.fn_GetParentValue = function() {
    scwin.key_acpt_no = frame.opener.scwin.key_acpt_no;
    scwin.key_reg_yn = frame.opener.scwin.key_reg_yn;
    scwin.key_mkt_nm = frame.opener.scwin.key_mkt_nm;
    key_isur_cd = frame.opener.key_isur_cd;
};


//선택한 정보 값 셋팅
scwin.fn_ReadInfo = function() {
    var url = "/InquiryDisclosure.do?method=getInquiryDsclRequest" + "&REQ_ACPT_NO=" + scwin.key_acpt_no + "&REG_YN=" + scwin.key_reg_yn + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.reset();
};



//등록 및 수정 처리
scwin.fn_Insert = function() {
    // 조회공시구분 selectbox 유효성 검증
    var vInqdiscls_tp_cd = $c.stf.getObjectValue(cmb_inqdiscls_tp_cd);
    if (vInqdiscls_tp_cd == ' ') {
        $c.win.alert("조회공시구분을 선택하세요");
        cmb_inqdiscls_tp_cd.focus();
        return;
    }

    // 조회공시 요구내용 유효성 검증
    var vReq_cont = $c.stf.getObjectValue(txa_req_cont);
    if (vReq_cont == '') {
        $c.win.alert("조회공시 요구내용을 입력하십시요.");
        txa_req_cont.focus();
        return;
    }

    // 공시시한 날짜 유효성 검증
    var vDeadlineDd = $c.stf.getObjectValue(edt_deadline_dd);
    if (vDeadlineDd.length < 8) {
        $c.win.alert("공시시한 날짜를 올바르게 입력하십시요.");
        edt_deadline_dd.focus();
        return;
    }

    // 공시시한 시간 유효성 검증
    var vDeadlineHhmm = $c.stf.getObjectValue(edt_deadline_hhmm);
    if (vDeadlineHhmm.length < 4) {
        $c.win.alert("공시시한 시간을 올바르게 입력하십시요.");
        edt_deadline_hhmm.focus();
        return;
    }

    //binding 되어 있지 않은 값들을 dts_MASTER에 저장
    dts_MASTER.setCellData(1, "INQDISCLS_REQ_ACPT_NO", scwin.key_acpt_no); //조회공시요구 접수번호
    dts_MASTER.setCellData(1, "INQDISCLS_REQ_TP_CD", $c.stf.getObjectValue(cmb_inqdiscls_tp_cd)); //조회공시구분
    dts_MASTER.setCellData(1, "INQDISCLS_REQ_GRND", $c.stf.getObjectValue(txa_law)); //근거
    dts_MASTER.setCellData(1, "REG_ID", js_id); //등록자ID
    //alert(dts_MASTER.text);

    var tmpStr = "저장 하시겠습니까?";

    // 수정모드일 때 메세지 변경
    if (scwin.key_reg_yn == 'Y') {
        tmpStr = "수정 하시겠습니까?";
    }
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_inquiry.Action = "/InquiryDisclosure.do?method=registerInquiryDsclRequest&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};





//조회공시요구서 삭제
scwin.fn_delete = function() {
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_MASTER.setCellData(1, "INQDISCLS_REQ_ACPT_NO", scwin.key_acpt_no); //조회공시요구 접수번호

        var url = "/InquiryDisclosure.do?method=deleteInquiryDsclRequest";
        url += "&REQ_ACPT_NO=" + scwin.key_acpt_no;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER)";
        trs_inquiry.Post();
    }
};
scwin.fn_Snd = function() {
    //수신자 체크 2016-10-10 KBoY		
    scwin.checkReceivers();
};
scwin.isFirst = true; //doCheckReceivers 에서 alert을 한번만 표시하기 위해
//조회공시요구서 Email 및 SMS 발송
// 발송대상 : 공시책임자, 공시담당자
scwin.doSend = function() {
    if (scwin.checkFileSize() == false) {
        $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        return false;
    }
    var first_result = false;
    scwin.isFirst = false;
    //첨부파일 창이 열려있지 않을 경우에 질문	
    if (grd_fileList.style.display == "none") {
        first_result = confirm("조회공시요구서 Email발송 시\n첨부파일을 포함하시겠습니까?");
    }
    var second_result;
    if (first_result) {
        //첨부파일 추가 시 Form화면으로 다시 돌아감
        $c.win.alert("첨부파일 추가 후 \n'조회공시요구서 발송' 버튼을 다시 클릭하세요");

        //파일업로드 컴포넌트 show=true 전환
        $c.stf.showObj(grd_fileList, true);
        $c.stf.showObj(lbl_tmp_2, true);
        $c.stf.showObj(label_5, true);
        $c.stf.showObj(btn_lineadd, true);
        $c.stf.showObj(btn_linedelete, true);
        $c.stf.showObj(txb_file_name, true);
    } else {
        if (confirm("공시책임자 및 공시담당자에게 Email과 SMS를 발송합니다.\n(Email 내용은 '미리보기'를 통해 확인 가능)\n계속하시겠습니까?")) {
            second_result = true;
        } else {
            if (!first_result) scwin.isFirst = true;

            else scwin.isFirst = false;
        }
    }
    if (second_result) // [확인] 버튼이 눌려졌을 경우

    {
        var tmp_mkt_id = '1';
        if (scwin.key_mkt_nm == '코스닥') {
            tmp_mkt_id = '2';
        } else if (scwin.key_mkt_nm == '코넥스') {
            tmp_mkt_id = '6';
        }
        dts_MASTER.setCellData(1, "INQDISCLS_REQ_ACPT_NO", scwin.key_acpt_no); //조회공시요구 접수번호

        var url = "/InquiryDisclosure.do?method=sendInquiryDsclRequest";
        url += "&REQ_ACPT_NO=" + scwin.key_acpt_no;
        url += "&MKM_NM=" + tmp_mkt_id;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_inquiry.Action = url;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_MASTER, I:pFile=dts_fileData)";
        trs_inquiry.Post();
    }
};



//SMS 수신인이 없는 경우 에러가 발생하여 미리 체크한다.
scwin.checkReceivers = function() {
    var url_list = "/InquiryDisclosure.do?method=checkReceivers&inputMessageId=MAIL_RECEIPTPLACE_OUT" + "&outputMessageId=MAIL_RECEIPTPLACE_OUT";
    var url_cond = "&ISUR_CD=" + key_isur_cd;
    // 그리드의 데이타 조회
    dts_receivers.DataID = encodeURI(url_list + url_cond);
    dts_receivers.reset();
};
scwin.doCheckReceivers = function() {
    var msg = '';
    var msg2 = '';
    var tmpChrgTpNm = '';
    var tmpPhoneNo = '';
    var tmpEmail = '';
    var isAddedPhoneMsg = false; //메세지 한번만 추가되도록
    var isAddedEmailMsg = false;
    for (var i = 1; i <= dts_receivers.getTotalRow(); i++) {
        tmpChrgTpNm = dts_receivers.getCellData(i, "CHRG_TP_NM");
        tmpPhoneNo = dts_receivers.getCellData(i, "CELLPHONE_NO");
        tmpEmail = dts_receivers.getCellData(i, "EMAIL");
        if (tmpPhoneNo == '') {
            msg += tmpChrgTpNm + '의 등록된 휴대폰 번호가 없습니다.\r\n';
            if (!isAddedPhoneMsg) {
                msg2 += "※ 휴대폰 번호가 없는 대상에게 알림용 'SMS 전송' 불가\r\n";
                isAddedPhoneMsg = true;
            }
        }
        if (tmpEmail == '') {
            msg += tmpChrgTpNm + '의 등록된 메일 주소가 없습니다.\r\n';
            if (!isAddedEmailMsg) {
                msg2 += "※ 메일 주소가 없는 대상에게 '요구서 전송' 불가\r\n";
                isAddedEmailMsg = true;
            }
        }
    }
    if (scwin.isFirst) {
        if (confirm(msg + msg2 + '계속 진행 하시겠습니까?')) {
            scwin.doSend();
        }
    } else scwin.doSend();
};


//20210716 else 부분 추가
scwin.showAlertMsg = function(msg) {
    if (msg.indexOf('50014') != -1) {
        $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else if (msg.indexOf('ORA-01400') != -1) {
        $c.win.alert('조회공시 요구서 수신 대상자 중 휴대폰 번호가 등록되어 있지 않은 대상자가 존재합니다.\r\n휴대폰 번호 등록 후 진행하시기 바랍니다.');
    } else {
        $c.win.alert('저장에실패했습니다');
    }
};



/**
 * 전체 파일 사이즈 체크
 */
scwin.checkFileSize = function() {
    var maxFileSize = 1024 * 30; //30MB		
    var totalFileSize = 0;
    var isValid = true;
    for (var i = 1; i <= dts_fileData.getTotalRow(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileData.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > maxFileSize) {
        //alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};
scwin.dts_receivers_OnLoadCompleted = function(rowcount) {
    scwin.doCheckReceivers();
};
scwin.img_cls_dd_onclick = function() {
    popUpCalendar2(edt_deadline_dd);
};
scwin.trs_inquiry_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_inquiry_OnFail = function() {
    scwin.showAlertMsg(trs_inquiry.ErrorMsg);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Insert();
};
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    //조회공시구분 컬럼값 셋팅	
    scwin.cmb_ColIndex = cmb_inqdiscls_tp_cd.IndexOfColumn("value", $c.stf.getObjectValue(txb_req_tp_cd));
    if (scwin.cmb_ColIndex != -1) {
        cmb_inqdiscls_tp_cd.setSelectedIndex(scwin.cmb_ColIndex);
    }
};
scwin.btn_Snd_onclick = function() {
    scwin.fn_Snd();
};
scwin.btn_Preview_onclick = async function() {
    var tmp_mkt_id = '1';
    if (scwin.key_mkt_nm == '코스닥') {
        tmp_mkt_id = '2';
    } else if (scwin.key_mkt_nm == '코넥스') {
        tmp_mkt_id = '6';
    }
    var url = "/InquiryDisclosure.do?method=previewInquiryDsclRequest";
    url += "&REQ_ACPT_NO=" + scwin.key_acpt_no;
    url += "&MKM_NM=" + tmp_mkt_id;
    await $c.frame.CreateDialogFrame("QUSET_PREVIEW", url, "조회공시요구서 미리보기", 200, 0, 610, 770, "window");
};
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (dts_fileData.getRowStatus(dts_fileData.getRowPosition()) == 0) {
        fn_filedown(dts_fileData.getCellData(row, "NOTI_SVC_ID"), dts_fileData.getCellData(row, "FILE_SEQ"));
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileData.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileData.insertRow();
    inf_find.open();
    var posV = Math.pow(10, 1);
    if (inf_find.getValue() != "") {
        var fileName = inf_find.getValue();
        if (fileName.indexOf('\') > 0) {,fileName=fileName.substring(fileName.lastIndexOf('\
                ')+1);,dts_fileData.setCellData(dts_fileData.getRowPosition(),"FILE_NAME",inf_find.getValue()),
                ///////////////////////////////////////////////////////
                dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileUrl", inf_find.getValue()), fileSize = inf_find.FileInfo('size'), fileSize = Math.round(fileSize / 1024 * posV) / posV, dts_fileData.setCellData(dts_fileData.getRowPosition(), "FILE_SIZE", fileSize), txb_file_name.setValue(inf_find.getValue()))), {
            dts_fileData: dts_fileData
        },
        function() {
            $c.cp.removeRow(dts_fileData, dts_fileData.getRowPosition());
        },
        function() {
            // 패널라운드 처리
            $c.libRoundPanel.PanelToGroupBox(panel_1);
            scwin.fn_GetParentValue();

            // hidden 객체 숨김
            $c.stf.showObj(txb_req_tp_cd, false);
            $c.stf.showObj(grd_fileList, false);
            $c.stf.showObj(lbl_tmp_2, false);
            $c.stf.showObj(label_5, false);
            $c.stf.showObj(btn_lineadd, false);
            $c.stf.showObj(btn_linedelete, false);
            $c.stf.showObj(txb_file_name, false);
            if (scwin.key_reg_yn == 'N') {
                //showObj(btn_Delete, false); // 등록모드라면 삭제버튼 숨김
                $c.stf.showObj(btn_Preview, false); // 등록모드라면 미리보기 버튼 숨김
                $c.stf.showObj(btn_Snd, false); // 등록모드라면 발송 버튼 숨김

            } else {
                btn_Save.src = "../img/btn_modify.gif";
            }



            //근거 항목 고정텍스트 설정	
            if (scwin.key_mkt_nm == '유가') {
                txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호 및 유가증권시장공시규정 제12조";
            } else if (scwin.key_mkt_nm == '코스닥') {
                txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호 및 코스닥시장공시규정 제10조";
            } else if (scwin.key_mkt_nm == '코넥스') {
                // 근거 내용 변경(20131030)
                //txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호, 코스닥시장공시규정 제50조의5";
                //txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호, 코스닥시장공시규정 제8조";
                txa_law.Text = "자본시장과 금융투자업에 관한 법률 제391조제2항제3호, 코넥스시장공시규정 제8조";
            }

            // 가우스헤더 셋팅
            dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INQDISCLSREQLISTPOPUP_INOUT";
            dts_MASTER.reset();
            dts_MASTER.insertRow();

            //파일DTS 셋팅
            dts_fileData.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_EMAIL_FILE_INOUT";
            dts_fileData.Reset();
            scwin.fn_ReadInfo();
            $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        },
        function() {
            $c.win.alert('dts_receivers.OnLoadError()');
        }))

}
};
